import CryptoKit
import Foundation

/// The roots the SDK trusts to authorise response-signing keys: the base64 of each root's 65-byte
/// uncompressed P-256 public key. Two, so a root can be retired without an outage: the backend
/// signs with `active`, and `standby` is ready to take over.
///
/// Generated by superwall/paywall-next `packages/response-signing/scripts/exportRootPublicKey.ts`
/// from each root's KMS key; paste the two lines it prints in place of the `= nil` line. Public keys
/// only. `nil` until the root's KMS key exists, and with no roots nothing verifies.
enum ResponseSigningRoots {
  static let active: String? = nil
  static let standby: String? = nil

  /// The configured roots. One that doesn't decode to a P-256 point is left out.
  static var all: [ResponseVerifier.TrustedRoot] {
    decode([active, standby].compactMap { $0 })
  }

  static func decode(_ encoded: [String]) -> [ResponseVerifier.TrustedRoot] {
    encoded
      .compactMap { SignatureEnvelope.canonicalBase64($0) }
      .filter { ResponseVerifier.uncompressedPoint($0) != nil }
      .map { ResponseVerifier.TrustedRoot(publicKey: $0) }
  }
}
